(()=>{'use strict';const B=Combat95,D=COMBAT_DATA,$=id=>document.getElementById(id),E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,loadError=null,history=[],page='field',result=null,entry=null,manual=false,position=0,velocity=0,target=0,frame=0,last=0,drag=null,draft=null,node=0,nodeTier=0,builderHistory=[],builderDrag=null,trayStamp="",builderCamera=null,builderCameraTarget=null,builderCameraFrame=0;
try{const raw=window.AndroidCombat?window.AndroidCombat.load():localStorage.getItem('arydia-combat95');state=raw?B.validate(JSON.parse(raw),D.templates):B.defaults();}catch(e){loadError=e;state=B.defaults();}history=state.undo||[];position=target=state.selected||0;
const current=()=>state.foes[state.selected],template=f=>D.templates.find(t=>t.key===f.template),attack=()=>state.attacks.find(w=>w.id===state.attack)||state.attacks[0];
function save(){if(loadError)throw Error('原战斗记录未能读取，已保留原始数据');const s=B.validate(state,D.templates),json=JSON.stringify(s);if(window.AndroidCombat){const message=window.AndroidCombat.save(json);if(message)throw Error(message);}else localStorage.setItem('arydia-combat95',json);}
function transaction(fn){const before=B.base(state),oldHistory=state.undo||[];try{fn();state.undo=[...oldHistory,before].slice(-30);while(JSON.stringify(state).length>640000&&state.undo.length)state.undo.shift();save();history=state.undo;$('undo').disabled=!history.length;}catch(e){state={...before,undo:oldHistory};history=oldHistory;toast(e.message);return false;}return true;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('on');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('on'),2300);}
function show(next){if(page==='editor'&&next!=='editor')draft=null;page=next;for(const p of ['field','models','attacks','editor'])$(p).hidden=p!==next;document.querySelectorAll('#tabs button').forEach(b=>b.setAttribute('aria-selected',b.dataset.page===next));$('tabs').hidden=next==='editor';if(next==='models')models();if(next==='attacks')attacks();if(next==='field'){requestAnimationFrame(()=>{layout();paint();});}}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').hidden=false;}
function close(){$('modal').hidden=true;$('modal-body').innerHTML='';}
function models(){const query=$('model-search').value.trim().replace(/^(敌人|FOE)[\s-]*/i,'').toUpperCase(),code=/^\d+$/.test(query)?String(+query):query;$('model-grid').innerHTML=D.enemies.filter(e=>!code||e.id===code).map(e=>`<button class="model-option" data-enemy="${E(e.id)}"><b>敌人-${E(e.id)}</b>${e.quantity?`<span>${e.quantity} 个${e.size?' · '+E(e.size):''}</span>`:''}</button>`).join('');}
function chooseEnemy(id){
 const code='FOE-'+id,ts=D.templates.filter(t=>t.cardId===code),hasPrimary=ts.some(t=>!t.scene&&!t.reference);
 const choices=ts.length>1?`<div class="card-choices">${ts.map((t,i)=>`<label><input type="checkbox" data-template="${E(t.key)}" ${(!t.scene&&!t.reference||!hasPrimary&&i===0)?'checked':''}><span>${E(t.sceneLabel||(t.reference?'参考卡面':t.variant+'号 · '+t.name))}</span></label>`).join('')}</div>`:'';
 modal(`敌人-${id}`,`<p>按实体敌人卡选择本场的目标，分别保留损伤记录。</p>${choices}<button class="primary" id="join">加入战场</button><p id="join-error" class="error"></p>`);
 $('join').onclick=()=>{
  if(!ts.length){$('join-error').textContent='这张卡尚未完成核对，暂不加入。';return;}
  const picked=ts.length===1?ts:ts.filter(t=>[...document.querySelectorAll('[data-template]:checked')].some(e=>e.dataset.template===t.key));
  if(!picked.length){$('join-error').textContent='请至少选择一张卡面。';return;}
  const incoming=picked.filter(t=>!state.foes.some(f=>f.template===t.key));
  if(state.foes.length+incoming.length>24){$('join-error').textContent='战场最多记录24个目标';return;}
  const first=state.foes.findIndex(f=>f.template===picked[0].key);
  if(!incoming.length){close();show('field');select(first);toast('已在战场中，保留原有记录');return;}
  if(transaction(()=>{const start=state.foes.length;for(const t of incoming)state.foes.push(B.instance(t,t.variant));state.selected=first>=0?first:start;})){close();position=target=state.selected;renderCards();show('field');}
 };
}

function cardLettering(t){
 if(!t.textOverlay)return '';
 const v=t.textOverlay,W=t.width,H=t.height,wide=W>H,cs=v.classes||[],note=v.note;
 const code=v.noCode?'':wide?`<text transform="translate(${W*.054} ${H*.156}) rotate(-90)" font-size="28" dominant-baseline="central">${E(v.cardId)}</text>`:`<text x="${W*.85}" y="${H*.059}" font-size="28">${E(v.cardId)}</text>`;
 const type='<g fill="white" font-family="serif" font-weight="600" stroke="#101914" stroke-width=".7" paint-order="stroke" text-anchor="middle">';
 const main=v.noFooter?'':`${type}<text x="${W*.535}" y="${H*.952}" font-size="40">${E(v.name)}</text>${cs.map((c,i)=>`<text x="${W*(wide?.89:.88)}" y="${H*(cs.length===1?.95:i===0?(wide?.855:.89):.95)}" font-size="28">${E(c)}</text>`).join('')}${code}</g>`;
 const header=v.header?`${type}<text x="${W*.355}" y="${H*.061}" font-size="34">${E(v.name)}</text>${code}</g>`:'';
 const words=line=>E(line).replace(/◎|♥|×|敏捷/g,word=>`<tspan fill="${word==='♥'||word==='×'?'#b62d38':'#50764e'}" font-weight="700">${word}</tspan>`);
 const body=note?`<g fill="${E(note.color||'#492f28')}" font-family="serif" font-size="${note.size||24}" text-anchor="${note.anchor==='start'?'start':'middle'}">${note.lines.map((line,i)=>`<text x="${W*note.x}" y="${H*(note.y+i*note.lineHeight)}">${words(line)}</text>`).join('')}</g>`:'';
 const labels=(v.labels||[]).map(l=>`<text x="${W*l.x}" y="${H*l.y}" font-family="serif" font-size="${l.size||26}" fill="${E(l.color||'#241f18')}" text-anchor="${l.anchor==='start'?'start':'middle'}">${words(l.text)}</text>`).join('');
 return `<svg class="card-lettering" viewBox="0 0 ${W} ${H}" aria-hidden="true">${main}${header}${body}${labels}</svg>`;
}

function renderCards(){
 const list=$('cards');list.innerHTML=state.foes.map((f,i)=>{const t=template(f);return `<div class="foe-card" data-foe="${i}" style="aspect-ratio:${t.width}/${t.height}"><img src="${E(t.image)}" alt="${E(t.name)} · ${f.index}号血量图" draggable="false" decoding="async" ${t.imageRotation?`style="position:absolute;left:50%;top:50%;width:${t.height/t.width*100}%;height:${t.width/t.height*100}%;transform:translate(-50%,-50%) rotate(90deg)"`:""}>${cardLettering(t)}<svg class="overlay" viewBox="0 0 ${t.width} ${t.height}" data-overlay="${i}"></svg></div>`;}).join('');
 list.querySelectorAll('img').forEach(img=>img.decode().then(()=>{if(img.isConnected)img.parentElement.classList.add('is-ready');}).catch(()=>{if(img.isConnected)img.parentElement.classList.add('load-error');}));
 $('empty').hidden=state.foes.length>0;$('controls').style.visibility=state.foes.length||history.length?'visible':'hidden';layout();paint();
}
function layout(){const width=$('stage').clientWidth,step=Math.min(width*.79,375),height=$('stage').clientHeight;document.querySelectorAll('.foe-card').forEach((card,i)=>{const t=template(state.foes[i]),baseWidth=Math.min(width*(t.width>t.height?.88:.78),520,height*.96*t.width/t.height),baseHeight=baseWidth*t.height/t.width,d=i-position,scale=1-Math.min(Math.abs(d),1)*.115;card.style.width=baseWidth+'px';card.style.height=baseHeight+'px';card.style.transform=`translate(calc(-50% + ${d*step}px), -50%) perspective(1000px) rotateY(${-Math.max(-1,Math.min(1,d))*6}deg) scale(${scale})`;card.style.opacity=String(1-Math.min(Math.abs(d),2)*.16);card.style.zIndex=String(100-Math.round(Math.abs(d)*10));});}
function animate(time){if(!frame)return;const dt=Math.min(.028,(time-last)/1000||.016);last=time;if(!drag){velocity+=(target-position)*180*dt;velocity*=Math.exp(-25*dt);position+=velocity*dt;if(Math.abs(target-position)<.001&&Math.abs(velocity)<.005){position=target;velocity=0;layout();frame=0;return;}}layout();frame=requestAnimationFrame(animate);}
function spring(){if(!frame){last=performance.now();frame=requestAnimationFrame(animate);}}
function select(index){index=Math.max(0,Math.min(state.foes.length-1,index));state.selected=index;target=index;entry=null;result=null;try{save();}catch(e){toast(e.message);}spring();paint();}

function marker(t,n,m,forecast=false){
 const x=(n.drawX??n.x)*t.width,y=(n.drawY??n.y)*t.height,r=n.r*t.width;
 if(m===2){const a=r*.77,b=r*.60;return `<g class="hp-marker ${forecast?'is-forecast':''}"><rect class="cube-face" x="${x-a}" y="${y-a}" width="${a*2}" height="${a*2}" rx="${r*.18}"/><path class="cube-top" d="M${x-a+3} ${y-a+3}H${x+a-3}L${x+b} ${y-b}H${x-b}Z"/><path class="cube-side" d="M${x+a-3} ${y-a+3}V${y+a-3}L${x+b} ${y+b}V${y-b}Z"/><rect x="${x-b}" y="${y-b}" width="${b*2}" height="${b*2}" rx="${r*.14}" fill="none" stroke="#f8bbd0" stroke-width="1.4" opacity=".6"/></g>`;}
 if(m===1)return '<g class="hp-armor" aria-hidden="true"></g>';
 if(n.kind==='armor'||n.armor){const bx=x+r*.79,by=y-r*.79,br=r*.37;return `<g class="${forecast?'preview-armor':'hp-armor-broken'}"><circle cx="${bx}" cy="${by}" r="${br}"/><path d="M${bx-br*.55} ${by+br*.55}L${bx+br*.55} ${by-br*.55}" fill="none" stroke="var(--ink)" stroke-width="2.5"/></g>`;}
 return '';
}
function tierPattern(w,tier){const indices=new Map();const nodes=w.nodes.filter((n,i)=>{if(n.tier>tier)return false;indices.set(i,indices.size);return true;}).map((n,i)=>({...n,parent:i?indices.get(n.parent):-1}));return {...w,nodes};}
function patternView(w){const ps=positions(w),xs=ps.map(p=>p.x),ys=ps.map(p=>p.y),minX=Math.min(...xs)-36,minY=Math.min(...ys)-44,width=Math.max(...xs)-minX+36,height=Math.max(...ys)-minY+36;return `${minX} ${minY} ${width} ${height}`;}
function weaponTray(){
 const stamp=JSON.stringify([state.attacks,state.attack,state.tier]);if(stamp===trayStamp)return;trayStamp=stamp;
 const tray=$('weapon-tray'),scroll=tray.scrollLeft;
 tray.innerHTML=state.attacks.map(w=>{const tiers=[...new Set(w.nodes.map(n=>n.tier))].sort();return `<article class="weapon-card ${w.id===state.attack?'is-active':''} ${tiers.length===1?'is-single':''}"><b class="weapon-title">${E(w.name)}</b><div class="weapon-patterns">${tiers.map(tier=>{const pattern=tierPattern(w,tier);return `<button class="weapon-pattern" data-forecast-attack="${E(w.id)}" data-forecast-tier="${tier}" aria-label="使用${E(w.name)}的${['白色','灰色','深色'][tier]}图案" aria-pressed="${w.id===state.attack&&state.tier===tier}"><span class="damage-dot ${['white','gray','dark'][tier]}"></span><svg viewBox="${patternView(pattern)}" aria-hidden="true">${diagram(pattern)}</svg></button>`;}).join('')}</div></article>`;}).join('')+'<button class="weapon-new" data-new-attack aria-label="自定义攻击轨迹"><span>＋</span>自定义</button>';
 tray.scrollLeft=scroll;
}
function paint(){
 const f=current(),w=attack();$('count').textContent=state.foes.length?`${state.foes.length} 张卡面 · ${state.selected+1} / ${state.foes.length}`:'尚未选择敌人';
 $('direction').textContent=w.aimed?'瞄准攻击':`进入方向 · ${B.dirs[w.entry][2]}`;
 const tCurrent=f?template(f):null;$('manual').disabled=!!tCurrent?.reference;$('hint').textContent=tCurrent?.reference?'说明卡面':tCurrent?.manualOnly?'触碰生命点或冰块记录状态':manual?'触碰血量点记录损伤':'选图案，再触碰血量点';
 $('confirm').disabled=!result?.valid;$('forecast').hidden=!result?.valid;$('combat').classList.toggle('has-forecast',!!result?.valid);
 $('result').textContent=result?.valid?`${result.wounds} 处受伤${result.armor?' · '+result.armor+' 处破甲':''}${result.defeated?' · 击败':result.weak.length?' · '+result.weak.length+' 处弱点':''}`:'';
 if(f){const t=template(f);$('actor-meta').innerHTML=`<b>${E(t.name)}</b> ${E(t.cardId.replace('FOE-','敌人-'))} · ${t.reference?'说明卡面':t.scene?'场景卡':f.index+'号'}`;}else $('actor-meta').innerHTML='';
 weaponTray();
 document.querySelectorAll('[data-overlay]').forEach(svg=>{
  const index=+svg.dataset.overlay,foe=state.foes[index],t=template(foe),active=index===state.selected,proposal=active&&result?.valid?result:null,allowed=active&&!manual&&!t.manualOnly&&!t.reference?B.entries(t,foe,w):[];
  let markup=t.nodes.map((n,j)=>{const changed=proposal&&proposal.marks[j]!==foe.marks[j];return marker(t,n,changed?proposal.marks[j]:foe.marks[j],!!changed);}).join('');
  if(active)markup+=t.nodes.map((n,j)=>`${allowed.includes(j)?`<circle class="hp-entry" cx="${(n.drawX??n.x)*t.width}" cy="${(n.drawY??n.y)*t.height}" r="${n.r*t.width*1.13}"/>`:''}<circle class="hp-target" data-hp="${j}" fill="transparent" cx="${(n.drawX??n.x)*t.width}" cy="${(n.drawY??n.y)*t.height}" r="${Math.max(n.r*t.width*1.4,27)}"/>`).join('');
  svg.innerHTML=markup;
 });
}
function hit(index){const f=current(),t=template(f);if(t.reference)return;if(t.manualOnly||manual){if(transaction(()=>{if(t.nodes[index].armorOnly){f.marks[index]=f.marks[index]===2?1:2;return;}f.marks[index]=f.marks[index]===1?0:f.marks[index]===0?2:(t.nodes[index].kind==='armor'||t.nodes[index].armor)?1:0;}))paint();return;}entry=index;result=B.preview(t,f,attack(),state.tier,index);paint();}
function pointFromEvent(e){const card=document.querySelector(`.foe-card[data-foe="${state.selected}"]`);if(!card||!card.classList.contains('is-ready'))return null;const rect=card.getBoundingClientRect(),t=template(current()),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height;const nearest=t.nodes.map((p,j)=>({j,d:Math.hypot(((p.drawX??p.x)-x)*rect.width,((p.drawY??p.y)-y)*rect.height)})).sort((a,b)=>a.d-b.d)[0];return nearest&&nearest.d<28?nearest.j:null;}
$('stage').addEventListener('pointerdown',e=>{if(!e.isPrimary||!state.foes.length)return;const hp=pointFromEvent(e);drag={x:e.clientX,y:e.clientY,time:e.timeStamp,from:position,lastX:e.clientX,v:0,kind:hp!==null&&!manual&&!template(current()).manualOnly?'aim':null};if(drag.kind==='aim')hit(hp);$('stage').setPointerCapture(e.pointerId);});
$('stage').addEventListener('pointermove',e=>{if(!drag){if(e.pointerType==='mouse'&&!manual&&state.foes.length&&!template(current()).manualOnly&&!template(current()).reference){const hp=pointFromEvent(e);if(hp!==null&&hp!==entry)hit(hp);}return;}if(drag.kind==='aim'){const hp=pointFromEvent(e);if(hp!==null&&hp!==entry)hit(hp);return;}const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.kind&&Math.max(Math.abs(dx),Math.abs(dy))>7)drag.kind=Math.abs(dx)>Math.abs(dy)*1.2?'horizontal':'vertical';if(drag.kind!=='horizontal')return;const step=Math.min($('stage').clientWidth*.79,375);let next=drag.from-dx/step;if(next<0)next=-Math.log1p(-next)*.23;else if(next>state.foes.length-1)next=state.foes.length-1+Math.log1p(next-state.foes.length+1)*.23;position=next;drag.v=(e.clientX-drag.lastX)/Math.max(1,e.timeStamp-drag.time);drag.lastX=e.clientX;drag.time=e.timeStamp;layout();});
function release(e,cancel=false){if(!drag)return;const d=drag;drag=null;if(d.kind==='horizontal'){const delta=position-d.from,fast=Math.abs(d.v)>.42;select(cancel?state.selected:state.selected+(Math.abs(delta)>.20||fast?(delta>0?1:-1):0));}else if(!cancel&&!d.kind){const index=pointFromEvent(e);if(index!==null)hit(index);}else{target=state.selected;spring();}}
$('stage').addEventListener('pointerup',e=>release(e));$('stage').addEventListener('pointercancel',e=>release(e,true));
function positions(w){const out=[{x:0,y:0}];for(const n of w.nodes.slice(1)){const p=out[n.parent];out.push({x:p.x+n.dx*66,y:p.y+n.dy*66});}return out;}
function shape(p,r=18){return Array.from({length:16},(_,i)=>{const a=Math.PI*2*i/16,d=i%2?r*.83:r;return `${p.x+Math.sin(a)*d},${p.y-Math.cos(a)*d}`;}).join(' ');}
function diagram(w,selected=-1,interactive=false){const ps=positions(w),colors=['#fff','#bcbdc0','#58595b'];let s=`<defs><marker id="tip${interactive?'builder':'mini'+w.id}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#344a40"/></marker></defs>`;s+=w.nodes.slice(1).map((n,i)=>`<path class="step-link" marker-end="url(#tip${interactive?'builder':'mini'+w.id})" d="M${ps[n.parent].x} ${ps[n.parent].y}L${ps[i+1].x} ${ps[i+1].y}"/>`).join('');s+=w.nodes.map((n,i)=>`${n.piercing?`<path d="M${ps[i].x} ${ps[i].y-25}l25 25-25 25-25-25Z" fill="none" stroke="#368b9d" stroke-width="3"/>`:''}<polygon class="attack-step ${i===selected?'is-selected':''}" data-step="${i}" points="${shape(ps[i])}" fill="${colors[n.tier]}"/>${i===0?`<circle cx="0" cy="0" r="4" fill="#344a40"/>`:''}`).join('');if(interactive&&selected>=0){const p=ps[selected];s+=B.dirs.map(([x,y])=>`<circle class="builder-ghost" cx="${p.x+x*66}" cy="${p.y+y*66}" r="16"/>`).join('');}return s;}
function attacks(){$('attack-list').innerHTML=state.attacks.map(w=>`<div class="attack-option"><button class="icon" data-use="${E(w.id)}" aria-label="使用${E(w.name)}"><svg viewBox="-125 -105 250 210">${diagram(w)}</svg></button><div><b>${E(w.name)}</b><small>${w.nodes.length} 击 · ${w.aimed?'瞄准攻击':'定向攻击'}</small></div><button class="edit" data-edit="${E(w.id)}">编辑</button></div>`).join('');}
function edit(w){draft=B.clone(w);node=0;nodeTier=0;builderHistory=[];builderCamera=null;builderCameraTarget=null;show('editor');$('attack-name').value=draft.name;drawBuilder();}

function setBuilderCamera(){if(!builderCamera)return;$('builder').setAttribute('viewBox',`${builderCamera.x} ${builderCamera.y} ${builderCamera.size} ${builderCamera.size}`);}
function fitBuilderCamera(ps){
 const xs=ps.map(p=>p.x),ys=ps.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
 const size=Math.max(360,maxX-minX+150,maxY-minY+150);
 if(!builderCamera){builderCamera={x:(minX+maxX-size)/2,y:(minY+maxY-size)/2,size};setBuilderCamera();return;}
 if(builderDrag)return;
 const c=builderCameraTarget||builderCamera;
 if(minX>c.x+48&&maxX<c.x+c.size-48&&minY>c.y+48&&maxY<c.y+c.size-48)return;
 builderCameraTarget={x:(minX+maxX-size)/2,y:(minY+maxY-size)/2,size};
 if(builderCameraFrame)return;
 let last=performance.now();
 const tick=time=>{if(!draft||!builderCameraTarget){builderCameraFrame=0;return;}const dt=Math.min(.04,(time-last)/1000);last=time;const k=1-Math.exp(-14*dt),to=builderCameraTarget;for(const key of ['x','y','size'])builderCamera[key]+=(to[key]-builderCamera[key])*k;setBuilderCamera();if(Math.max(...['x','y','size'].map(key=>Math.abs(to[key]-builderCamera[key])))<.05){builderCamera={...to};builderCameraTarget=null;setBuilderCamera();builderCameraFrame=0;return;}builderCameraFrame=requestAnimationFrame(tick);};builderCameraFrame=requestAnimationFrame(tick);
}
function drawBuilder(){
 const ps=positions(draft);fitBuilderCamera(ps);
 const grid='<defs><pattern id="builder-grid" width="66" height="66" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="18" fill="none" stroke="#879a8b" stroke-width="1" opacity=".17"/></pattern></defs><rect x="-2000" y="-2000" width="4000" height="4000" fill="url(#builder-grid)" pointer-events="none"/>';
 $('builder').innerHTML=grid+diagram(draft,node,true);$('piercing').setAttribute('aria-pressed',draft.nodes[node].piercing);$('aimed').setAttribute('aria-pressed',draft.aimed);$('aimed').textContent=draft.aimed?'瞄准攻击':'定向攻击';document.querySelectorAll('[data-node-tier]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.nodeTier===draft.nodes[node].tier));
}
function builderPoint(e){const matrix=$('builder').getScreenCTM(),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());return{x:p.x,y:p.y};}
$('builder').addEventListener('pointerdown',e=>{if(!e.isPrimary)return;const p=builderPoint(e),ps=positions(draft),near=ps.map((q,i)=>({i,d:Math.hypot(p.x-q.x,p.y-q.y)})).sort((a,b)=>a.d-b.d)[0];if(near.d>31)return;node=near.i;nodeTier=draft.nodes[node].tier;drawBuilder();builderDrag={from:ps[node],dx:0,dy:0,moved:false};$('builder').setPointerCapture(e.pointerId);});
$('builder').addEventListener('pointermove',e=>{if(!builderDrag)return;const p=builderPoint(e),dx=p.x-builderDrag.from.x,dy=p.y-builderDrag.from.y;if(Math.hypot(dx,dy)<20)return;builderDrag.moved=true;const angle=Math.round(Math.atan2(dy,dx)/(Math.PI/4))*Math.PI/4;builderDrag.dx=Math.round(Math.cos(angle));builderDrag.dy=Math.round(Math.sin(angle));drawBuilder();const a=builderDrag.from;$('builder').insertAdjacentHTML('beforeend',`<path class="step-link" stroke-dasharray="5 5" d="M${a.x} ${a.y}L${p.x} ${p.y}"/><polygon class="builder-ghost" points="${shape({x:a.x+builderDrag.dx*66,y:a.y+builderDrag.dy*66})}"/>`);});
$('builder').addEventListener('pointerup',()=>{if(builderDrag?.moved){if(draft.nodes.length>=20)toast('每个轨迹最多20击');else{builderHistory.push(B.clone(draft));draft.nodes.push({parent:node,dx:builderDrag.dx,dy:builderDrag.dy,tier:Math.max(nodeTier,draft.nodes[node].tier),piercing:false});node=draft.nodes.length-1;}}builderDrag=null;drawBuilder();});$('builder').addEventListener('pointercancel',()=>{builderDrag=null;drawBuilder();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.forecastAttack){state.attack=b.dataset.forecastAttack;state.tier=+b.dataset.forecastTier;entry=result=null;try{save();}catch(error){toast(error.message);}paint();}if(b.hasAttribute('data-new-attack'))edit(B.blankAttack());if(b.dataset.page)show(b.dataset.page);if(b.dataset.enemy)chooseEnemy(b.dataset.enemy);if(b.dataset.tier){state.tier=+b.dataset.tier;document.querySelectorAll('[data-tier]').forEach(p=>p.setAttribute('aria-pressed',p===b));if(entry!==null)result=B.preview(template(current()),current(),attack(),state.tier,entry);save();paint();}if(b.dataset.use){state.attack=b.dataset.use;save();entry=result=null;show('field');paint();}if(b.dataset.edit)edit(state.attacks.find(w=>w.id===b.dataset.edit));if(b.dataset.nodeTier){const value=+b.dataset.nodeTier;if(node===0&&value!==0){toast('起点属于第一档，请先拖出下一击');return;}if(node>0&&value<draft.nodes[draft.nodes[node].parent].tier){toast('此击不能早于前一击出现');return;}builderHistory.push(B.clone(draft));draft.nodes[node].tier=value;draft.nodes.forEach((n,i)=>{if(i)n.tier=Math.max(n.tier,draft.nodes[n.parent].tier);});nodeTier=value;drawBuilder();}});
$('model-search').oninput=models;$('add').onclick=()=>show('models');$('close-modal').onclick=close;document.querySelector('.scrim').onclick=close;$('back').onclick=()=>{if(!$('modal').hidden)close();else if(page==='editor')show('attacks');else if(page!=='field')show('field');else window.AndroidCombat?.close();};
$('manual').onclick=()=>{manual=!manual;$('manual').setAttribute('aria-pressed',manual);entry=result=null;paint();};$('confirm').onclick=()=>{if(!result?.valid)return;const proposal=result;if(transaction(()=>{current().marks=[...proposal.marks];})){result=entry=null;paint();toast(proposal.defeated?'全部生命点已受伤':proposal.weak.length?'请结算原卡的弱点效果':'已记录本次攻击');}};
$('undo').onclick=()=>{if(!history.length)return;const old=state,remaining=history.slice(0,-1);state={...history[history.length-1],undo:remaining};try{save();}catch(e){state=old;toast(e.message);return;}history=remaining;result=entry=null;position=target=state.selected;$('undo').disabled=!history.length;renderCards();};
$('direction').onclick=()=>{const w=attack(),order=[7,0,1,6,-1,2,5,4,3];modal('攻击进入方向',`<div class="direction-grid">${order.map(i=>i<0?`<button id="aim-mode" data-on="${w.aimed}">瞄准</button>`:`<button data-dir="${i}" data-on="${!w.aimed&&w.entry===i}">${['↓','↙','←','↖','↑','↗','→','↘'][i]}<br>${B.dirs[i][2]}</button>`).join('')}</div>`);document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{w.entry=+b.dataset.dir;w.aimed=false;entry=result=null;save();close();paint();});$('aim-mode').onclick=()=>{w.aimed=true;entry=result=null;save();close();paint();};};
$('new-attack').onclick=()=>edit(B.blankAttack());$('cancel-editor').onclick=()=>show('attacks');$('builder-undo').onclick=()=>{if(builderHistory.length){draft=builderHistory.pop();node=Math.min(node,draft.nodes.length-1);drawBuilder();}};$('piercing').onclick=()=>{builderHistory.push(B.clone(draft));draft.nodes[node].piercing=!draft.nodes[node].piercing;drawBuilder();};$('aimed').onclick=()=>{builderHistory.push(B.clone(draft));draft.aimed=!draft.aimed;drawBuilder();};
$('delete-node').onclick=()=>{if(!node)return;builderHistory.push(B.clone(draft));const removed=new Set([node]);draft.nodes.forEach((n,i)=>{if(removed.has(n.parent))removed.add(i);});const indices=new Map();draft.nodes=draft.nodes.filter((n,i)=>{if(removed.has(i))return false;indices.set(i,indices.size);return true;});draft.nodes.forEach((n,i)=>{if(i)n.parent=indices.get(n.parent);});node=0;drawBuilder();};
$('save-attack').onclick=()=>{draft.name=$('attack-name').value.trim()||'我的攻击';const copy=B.clone(draft);if(transaction(()=>{const i=state.attacks.findIndex(w=>w.id===copy.id);if(i<0)state.attacks.push(copy);else state.attacks[i]=copy;state.attack=copy.id;})){toast('攻击轨迹已保存');draft=null;show('attacks');}};
function overview(){
 modal('战场总览',state.foes.map((f,i)=>{const t=template(f);return `<div class="roster-row"><button class="selection" data-focus="${i}"><b>${E(t.name)}${t.reference||t.scene?'':' · '+f.index}</b><span>${t.reference?'说明卡面':t.manualOnly?'场景记录':f.marks.filter(m=>m===2).length+' / '+f.marks.length}</span></button><button class="roster-remove" data-remove="${i}" aria-label="移出${E(t.name)}">移出</button>${t.notice?`<p class="roster-notice">${E(t.notice)}</p>`:''}</div>`;}).join('')+(state.foes.length?'<button id="clear-field">结束本场战斗</button>':'<p>尚未加入敌人</p>'));
 document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{select(+b.dataset.focus);close();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=+b.dataset.remove;if(transaction(()=>{state.foes.splice(i,1);state.selected=Math.max(0,Math.min(state.selected,state.foes.length-1));})){position=target=state.selected;entry=result=null;renderCards();overview();toast('已移出，可撤销恢复');}});
 if($('clear-field'))$('clear-field').onclick=()=>{modal('结束本场战斗','<p>清空本场敌人与损伤记录，保留已保存的攻击轨迹。可用撤销恢复。</p><div class="roster-actions"><button id="keep-field">继续战斗</button><button id="confirm-clear" class="primary">结束本场</button></div>');$('keep-field').onclick=overview;$('confirm-clear').onclick=()=>{if(transaction(()=>{state.foes=[];state.selected=0;})){position=target=0;entry=result=null;renderCards();close();toast('本场已结束，可撤销恢复');}};};
}
$('overview').onclick=overview;
window.addEventListener('resize',layout);window.CombatApp={snapshot:()=>B.clone(state),templates:D.templates,back:()=>$('back').click()};renderCards();models();$('undo').disabled=!history.length;if(loadError)modal('战斗记录暂时无法读取','<p>原始记录已保留，当前不会覆盖它。请先使用软件的存档备份功能保留数据。</p>');
})();
